  const qualityComment = avgScore > 4 ? "\u5408\u4F5C\u8D28\u91CF\u6781\u9AD8" : avgScore > 3 ? "\u5408\u4F5C\u8D28\u91CF\u826F\u597D" : avgScore > 0 ? "\u5408\u4F5C\u8D28\u91CF\u4E00\u822C" : "\u8D28\u91CF\u6570\u636E\u4E0D\u8DB3";
